{
  "permissions": {
    "defaultMode": "plan",
    "allow": [
      "Bash(npm run test:*)",
      "Bash(npm run lint)",
      "Bash(git status)",
      "Bash(git diff:*)"
    ],
    "ask": [
      "Bash(git push:*)"
    ],
    "deny": [
      "Read(./.env)",
      "Read(./.env.*)",
      "Read(./secrets/**)",
      "Bash(curl:*)"
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "f=$(jq -r '.tool_input.file_path // empty'); case \"$f\" in *.env|*package-lock.json) echo \"Blocked: $f is protected\" >&2; exit 2;; esac; exit 0"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "jq -r '.tool_input.file_path // empty' | xargs -r npx prettier --write --ignore-unknown",
            "timeout": 30
          }
        ]
      }
    ]
  }
}

# 1. Keep the secret in your environment, never in the repo
export GITHUB_PAT="ghp_xxx_read_only_token"

# 2. Shared, committed config (project scope) using env expansion
cat > .mcp.json <<'EOF'
{
  "mcpServers": {
    "github": {
      "type": "http",
      "url": "https://api.githubcopilot.com/mcp/",
      "headers": { "Authorization": "Bearer ${GITHUB_PAT}" }
    }
  }
}
EOF

# Alternative: a local stdio server (default transport, local scope)
# claude mcp add my-db --env DATABASE_URL="$DATABASE_URL" -- npx -y <trusted-db-mcp-package>

# 3. Verify
claude mcp list
claude mcp get github

# 4. Ask a question (approve the project server and the tool call when prompted)
claude "Using the github MCP server, list the 5 most recent open issues in my-org/my-repo and summarise them"

# Inside an interactive session: /mcp shows status and tools; /mcp also handles OAuth
